def E(a, b, c):
    """Calculates E(a, b, c) = ((a+b+c)(ab+bc+ca)+a+b+c) / (4abc)"""
    sigma1 = a + b + c
    sigma2 = a*b + b*c + c*a
    sigma3 = a*b*c

    # Numerator = (a+b+c)(ab+bc+ca) + (a+b+c)
    numerator = sigma1 * (sigma2 + 1)
    denominator = 4 * sigma3

    if denominator == 0:
        return None # Should not happen for positive integers

    return numerator / denominator

# Search parameters
max_sum = 20
found_n1 = []
found_n2 = []

# Iterate through distinct positive integers a < b < c such that a+b+c <= 20
for a in range(1, max_sum):
    for b in range(a + 1, max_sum - a):
        # c must be > b and a+b+c <= 20 => c <= 20 - a - b
        for c in range(b + 1, max_sum - a - b + 1):

            if a + b + c > max_sum:
                # Optimization: break inner loop if sum exceeds limit
                break

            result = E(a, b, c)

            if result == 1.0:
                found_n1.append((a, b, c))
            elif result == 2.0:
                found_n2.append((a, b, c))

print("--- Results for n=1 ---")
if found_n1:
    for triple in found_n1:
        print(f"Triple: {triple}, Sum: {sum(triple)}")
else:
    print("No triples found for n=1 within the given constraints.")

print("\n--- Results for n=2 ---")
if found_n2:
    for triple in found_n2:
        print(f"Triple: {triple}, Sum: {sum(triple)}")
else:
    print("No triples found for n=2 within the given constraints.")
